import{_ as t,o,c as s,ag as i}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"GitHub basics","description":"","frontmatter":{"source":"setup/github-basics.md"},"headers":[],"relativePath":"setup/github-basics.md","filePath":"setup/github-basics.md"}'),a={name:"setup/github-basics.md"};function r(n,e,l,d,h,c){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="github-basics" tabindex="-1">GitHub basics <a class="header-anchor" href="#github-basics" aria-label="Permalink to &quot;GitHub basics&quot;">​</a></h1><blockquote><p>Everything you build in this course is saved on GitHub. This page teaches the parts you need, starting from zero, using only your browser.</p></blockquote><p>You&#39;ll use this page mostly in weeks 1–5. You first open a Codespace in week 4, and from week 6 you work in one (<a href="./codespaces.html">GitHub Codespaces</a>); the same ideas carry over. For a one-page summary of git commands, see the <a href="./../resources/git-cheatsheet.html">git cheat sheet</a>.</p><h2 id="what-git-and-github-are" tabindex="-1">What Git and GitHub are <a class="header-anchor" href="#what-git-and-github-are" aria-label="Permalink to &quot;What Git and GitHub are&quot;">​</a></h2><p><strong>Git</strong> is a tool that records the history of a folder of files. Each time you save a snapshot, called a <strong>commit</strong>, git remembers exactly what every file looked like. You can compare any two snapshots and go back to an earlier one. In this course, a commit is your <strong>save point</strong>: if the AI breaks something, you return to the last one that worked.</p><p><strong>GitHub</strong> is a website that stores git folders online and adds useful extras: a web editor, a place to publish websites (GitHub Pages), cloud computers for coding (Codespaces) and an AI assistant (Copilot).</p><p>A few words you&#39;ll see everywhere (more in the <a href="./../resources/glossary.html">glossary</a>):</p><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Repository</strong> (repo)</td><td>One project: a folder of files plus its full history</td></tr><tr><td><strong>Commit</strong></td><td>A saved snapshot of the repository, with a message saying what changed</td></tr><tr><td><strong>Branch</strong></td><td>A separate line of work. Every repo starts with one branch, called <code>main</code></td></tr><tr><td><strong>Push / pull</strong></td><td>Send your commits up to GitHub / bring commits down from GitHub. The web editor does this for you</td></tr><tr><td><strong>Diff</strong></td><td>The differences between two versions: lines removed (red) and added (green)</td></tr><tr><td><strong>Fork / template</strong></td><td>Ways to start your own repository from someone else&#39;s</td></tr><tr><td><strong>Pull request</strong> (PR)</td><td>A request to merge the commits on one branch into another, with a page for reading the diff and leaving comments. Taught in week 12</td></tr></tbody></table><h2 id="your-account-and-profile" tabindex="-1">Your account and profile <a class="header-anchor" href="#your-account-and-profile" aria-label="Permalink to &quot;Your account and profile&quot;">​</a></h2><p>If you haven&#39;t created your account yet, follow <a href="./accounts.html">Accounts</a> first. Then make your profile look like a portfolio, because it will become one:</p><ol><li>Click your profile photo (top right) → <strong>Your profile</strong> → <strong>Edit profile</strong>.</li><li>Add your name (optional), a one-line bio (&quot;Learning to build web apps with AI&quot;) and, if you like, a photo.</li><li>Later in the course, use <strong>Customize your pins</strong> on your profile page to show your best projects first.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Your username appears in the address of every site you publish: <code>https://[username].github.io</code>. You can change it in Settings, but every link you&#39;ve shared will break. If you&#39;re going to change it, do it before week 1.</p></div><h2 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h2><p>A repository is a project. In this course you&#39;ll create several:</p><table tabindex="0"><thead><tr><th>Repository</th><th>Weeks</th><th>What goes in it</th></tr></thead><tbody><tr><td><code>[username].github.io</code></td><td>1–4</td><td>Your home page, and your game in a <code>game/</code> folder</td></tr><tr><td>Project 1 (you choose the name)</td><td>5–8</td><td>A tool you&#39;d actually use</td></tr><tr><td>Project 2 (the AI micro-app)</td><td>9–10</td><td>An app with a server part</td></tr><tr><td>Capstone</td><td>11–16</td><td>Your final project</td></tr></tbody></table><p>Create all of them in your <strong>personal</strong> account, not in an organization, even if your class has one: Vercel&#39;s free plan, which you use from week 10, can&#39;t deploy private repositories owned by an organization.</p><p>Every repository should have a <strong>README.md</strong>: the page GitHub shows under the file list. It says what the project is and how to use it. You&#39;ll learn to write one <a href="#markdown-basics-for-readmes">below</a>.</p><h2 id="public-or-private" tabindex="-1">Public or private <a class="header-anchor" href="#public-or-private" aria-label="Permalink to &quot;Public or private&quot;">​</a></h2><p>When you create a repository, you choose:</p><ul><li><strong>Public:</strong> anyone on the internet can see the files and their <strong>entire history</strong>. This is how a portfolio works, and it&#39;s what the course expects for your projects.</li><li><strong>Private:</strong> only you, and people you invite, can see it. Good for practice.</li></ul><p>Two consequences matter:</p><ol><li><strong>GitHub Pages needs public repositories</strong> on a free account. Your home page and Project 1 must be public to be published.</li><li><strong>Anything you commit to a public repository is public forever</strong>, even if you delete it in a later commit, because the old version stays in the history. So never commit passwords, API keys, <code>.env</code> files, or personal information about other people. If a secret is ever committed, <strong>revoke it</strong> (cancel it at the service that issued it) and make a new one. Deleting the file isn&#39;t enough.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>What goes in a repository, and what goes on Canvas.</strong> Your public repositories hold your code, <code>SPEC.md</code>, <code>PROMPTS.md</code>, <code>TESTS.md</code> and READMEs. Graded personal writing goes on <strong>Canvas</strong>, the course&#39;s learning management system, and never in a repository: reflections, your AI journal, the signed safety contract, self-assessments, your personal AI-use rules, written peer reviews and pair contribution statements. Never put grades or classmates&#39; names in a repository.</p></div><h2 id="create-a-repository" tabindex="-1">Create a repository <a class="header-anchor" href="#create-a-repository" aria-label="Permalink to &quot;Create a repository&quot;">​</a></h2><ol><li>On any GitHub page, click <strong>+</strong> (top right) → <strong>New repository</strong>.</li><li><strong>Repository name:</strong> short, lowercase, words joined with hyphens, such as <code>habit-tracker</code>. (For your home page, the name must be exactly <code>[username].github.io</code>; see <a href="#publish-a-site-with-github-pages">GitHub Pages</a>.)</li><li><strong>Description:</strong> one sentence (optional).</li><li>Choose <strong>Public</strong> or <strong>Private</strong>.</li><li>Tick <strong>Add a README file</strong>. A README gives the repository its first commit, and some tools need that.</li><li>Click <strong>Create repository</strong>.</li></ol><p>✅ <strong>Checkpoint:</strong> you see your new repository with one file, <code>README.md</code>, and &quot;1 commit&quot; near the top of the file list.</p><h2 id="upload-files" tabindex="-1">Upload files <a class="header-anchor" href="#upload-files" aria-label="Permalink to &quot;Upload files&quot;">​</a></h2><p>This is how you&#39;ll publish the page you build in week 1, when you ship it in week 2.</p><ol><li>Open your repository and click <strong>Add file</strong> → <strong>Upload files</strong>.</li><li>Drag your files onto the page, or click <strong>choose your files</strong>.</li><li>Under <strong>Commit changes</strong>, write a message such as <code>Add first version of home page</code>.</li><li>Leave <strong>Commit directly to the <code>main</code> branch</strong> selected, and click <strong>Commit changes</strong>.</li></ol><p><strong>To put a file inside a folder:</strong> click <strong>Add file</strong> → <strong>Create new file</strong>, and type the folder name followed by a slash in the name box, for example <code>game/</code>. GitHub turns it into a folder. Then type the file name (<code>index.html</code>), paste the contents, and commit. You can&#39;t upload an empty folder; a folder exists only when there&#39;s a file in it.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>File names are <strong>case-sensitive</strong> on GitHub. <code>Index.html</code>, <code>index.HTML</code> and <code>index.html</code> are three different names. Web pages should use lowercase names with no spaces: <code>about-me.html</code>, not <code>About Me.html</code>.</p></div><h2 id="edit-a-file-and-commit-on-the-web" tabindex="-1">Edit a file and commit on the web <a class="header-anchor" href="#edit-a-file-and-commit-on-the-web" aria-label="Permalink to &quot;Edit a file and commit on the web&quot;">​</a></h2><ol><li>Click a file to open it, then click the <strong>pencil icon</strong> (Edit this file).</li><li>Make your change. The <strong>Preview</strong> tab shows how Markdown files will look.</li><li>Click <strong>Commit changes…</strong>, write a message, and click <strong>Commit changes</strong>.</li></ol><p>Each commit should be <strong>one small, working change</strong>, which is step 6 of the <a href="./../resources/safe-loop.html">Safe Loop</a>.</p><h3 id="write-a-good-commit-message" tabindex="-1">Write a good commit message <a class="header-anchor" href="#write-a-good-commit-message" aria-label="Permalink to &quot;Write a good commit message&quot;">​</a></h3><p>A commit message tells future-you what changed and why. Start with a verb and be specific.</p><table tabindex="0"><thead><tr><th>Weak</th><th>Better</th></tr></thead><tbody><tr><td><code>update</code></td><td><code>Add contact section with email link</code></td></tr><tr><td><code>fix</code></td><td><code>Fix score not resetting when game restarts</code></td></tr><tr><td><code>changes from AI</code></td><td><code>Make header sticky on small screens</code></td></tr></tbody></table><p><strong>When AI helped with a commit,</strong> add a blank line after the message and then an <code>Assisted-by:</code> line naming the tool. On the web, put it in the <strong>Extended description</strong> box. You learn this in week 3, and it&#39;s required from week 11 (safety contract <a href="./safety-contract.html#8-i-keep-a-record-of-what-i-wrote-myself">rule 8</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Make header sticky on small screens</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Assisted-by: Gemini (Canvas tool)</span></span></code></pre></div><h2 id="edit-several-files-at-once-with-githubdev" tabindex="-1">Edit several files at once with github.dev <a class="header-anchor" href="#edit-several-files-at-once-with-githubdev" aria-label="Permalink to &quot;Edit several files at once with github.dev&quot;">​</a></h2><p>From week 3 you&#39;ll often change more than one file at a time. <strong>github.dev</strong> is a lightweight version of the VS Code editor that opens in your browser, straight from any repository.</p><ol><li>Open your repository on github.com and <strong>press the <code>.</code> (full stop) key</strong>. (Or change <code>github.com</code> to <code>github.dev</code> in the address bar.)</li><li>The editor opens with your files in the <strong>Explorer</strong> on the left. Click a file to edit it.</li><li>When you&#39;ve made a change, click the <strong>Source Control</strong> icon on the left (it looks like a branching line). Your changed files are listed there.</li><li>Click a changed file to see a <strong>diff</strong>: old version on the left, new on the right.</li><li>Type a commit message in the box at the top and click <strong>Commit &amp; Push</strong>.</li></ol><p>✅ <strong>Checkpoint:</strong> back on github.com (refresh the page), your change and your commit message appear.</p><p>github.dev is free and doesn&#39;t use your Codespaces hours. But it <strong>can&#39;t run code</strong>: there&#39;s no terminal and no preview server. To see your page, use GitHub Pages or, from week 4, a Codespace.</p><h2 id="see-your-history" tabindex="-1">See your history <a class="header-anchor" href="#see-your-history" aria-label="Permalink to &quot;See your history&quot;">​</a></h2><p>Your history is the list of every commit: who made it, when, and what changed.</p><ul><li><strong>Whole repository:</strong> on the repository page, click the <strong>commits</strong> link (a clock icon with a number, near the top of the file list).</li><li><strong>One file:</strong> open the file and click <strong>History</strong>.</li><li><strong>One commit:</strong> click its message. You&#39;ll see the diff for every file it changed: red lines were removed, green lines were added.</li></ul><p>Reading diffs is a core skill in this course. It&#39;s step 5 of the Safe Loop: before you keep a change, read what actually changed.</p><h2 id="undo-a-change" tabindex="-1">Undo a change <a class="header-anchor" href="#undo-a-change" aria-label="Permalink to &quot;Undo a change&quot;">​</a></h2><p><strong>Before you commit:</strong> in the web editor, click <strong>Cancel changes</strong>. In github.dev, in the Source Control panel, hover over the file and click the <strong>Discard changes</strong> arrow.</p><p><strong>After you commit, on the web:</strong> there&#39;s no one-click undo for a commit, but you can put an old version back.</p><ol><li>Open the file&#39;s <strong>History</strong> and click the last commit where the file was right.</li><li>Click <strong>Browse files</strong> (or the <strong>…</strong> menu → <strong>View file</strong>) to see the repository as it was at that commit. Open your file.</li><li>Copy the whole file (the <strong>Copy raw file</strong> button, or open <strong>Raw</strong> and select everything).</li><li>Go back to the current version of the file, click the pencil icon, select everything, paste the old version over it, and commit with a message such as <code>Revert header to version before sticky change</code>.</li></ol><p><strong>In a Codespace (week 4 onward):</strong> the terminal command <code>git revert [commit-id]</code> makes a new commit that undoes an old one. See the <a href="./../resources/git-cheatsheet.html">git cheat sheet</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Reverting is easy when commits are small. If one commit changed twelve things, you can&#39;t undo just the one that broke. That&#39;s why the course asks for one commit per working step.</p></div><h2 id="markdown-basics-for-readmes" tabindex="-1">Markdown basics for READMEs <a class="header-anchor" href="#markdown-basics-for-readmes" aria-label="Permalink to &quot;Markdown basics for READMEs&quot;">​</a></h2><p><strong>Markdown</strong> is a simple way to format text using ordinary characters. README files, and most files in this course, are written in it. This:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Habit Tracker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">A tiny app for tracking </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**three daily habits**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">. Your data stays in your browser.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## How to use it</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Type a habit and press </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Add**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Tick it off each day.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Reload the page: your habits are still there.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Links</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Live site: [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">my habit tracker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://example.github.io/habit-tracker/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Built with the [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Safe Loop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">https://boyu-zhang-uoi.github.io/building-apps-with-ai/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Screenshot of the app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">docs/screenshot.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Feature | Status |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|---|---|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Add a habit | ✅ done |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Weekly chart | not started |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Run it locally with </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`python3 -m http.server 8000\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span></code></pre></div><p>…shows up on GitHub as a formatted page with a title, bold text, a numbered list, links, an image, a table and a bit of code.</p><table tabindex="0"><thead><tr><th>You type</th><th>You get</th></tr></thead><tbody><tr><td><code># Title</code>, <code>## Section</code></td><td>A big heading, a smaller heading</td></tr><tr><td><code>**bold**</code>, <code>*italic*</code></td><td><strong>bold</strong>, <em>italic</em></td></tr><tr><td><code>- item</code> or <code>1. item</code></td><td>A bulleted or numbered list</td></tr><tr><td><code>[text](https://…)</code></td><td>A link</td></tr><tr><td><code>![description](path/to/image.png)</code></td><td>An image (the description is read aloud by screen readers)</td></tr><tr><td><code>\`code\`</code></td><td><code>code</code> in a fixed-width font</td></tr><tr><td>A blank line</td><td>A new paragraph</td></tr></tbody></table><p>Use the <strong>Preview</strong> tab in GitHub&#39;s editor to check your formatting before you commit. The course&#39;s README template is <a href="./../templates/PROJECT_README.html">PROJECT_README.md template</a>.</p><h2 id="publish-a-site-with-github-pages" tabindex="-1">Publish a site with GitHub Pages <a class="header-anchor" href="#publish-a-site-with-github-pages" aria-label="Permalink to &quot;Publish a site with GitHub Pages&quot;">​</a></h2><p><strong>GitHub Pages</strong> turns a public repository into a website for free. It serves <strong>static</strong> files: HTML, CSS, JavaScript and images that the browser runs by itself, with no server code. That&#39;s everything you build in weeks 1–8.</p><p>The file a visitor sees first must be called <code>index.html</code>.</p><h3 id="your-home-page-usernamegithubio" tabindex="-1">Your home page: <code>[username].github.io</code> <a class="header-anchor" href="#your-home-page-usernamegithubio" aria-label="Permalink to &quot;Your home page: \`[username].github.io\`&quot;">​</a></h3><p>Your home page lives in a repository with a special name. If your username is <code>alexkim</code>, the repository must be called <code>alexkim.github.io</code>, and the site appears at <code>https://alexkim.github.io</code>.</p><ol><li>Create a <strong>public</strong> repository named exactly <code>[username].github.io</code>, using your own username in lowercase (<a href="#create-a-repository">how</a>).</li><li>Upload your page as <code>index.html</code>, at the top level of the repository, not inside a folder (<a href="#upload-files">how</a>).</li><li>Go to the repository&#39;s <strong>Settings</strong> tab → <strong>Pages</strong> (left sidebar).</li><li>Under <strong>Build and deployment</strong>, check that <strong>Source</strong> is <strong>Deploy from a branch</strong> and <strong>Branch</strong> is <strong><code>main</code></strong> with the folder <strong><code>/ (root)</code></strong>. If not, choose them and click <strong>Save</strong>.</li><li>Wait a minute or two. To watch progress, open the <strong>Actions</strong> tab: a run called <strong>pages build and deployment</strong> turns into a green tick when the site is live.</li><li>Back in <strong>Settings</strong> → <strong>Pages</strong>, a banner says <strong>Your site is live at…</strong>. Click <strong>Visit site</strong>.</li></ol><p>✅ <strong>Checkpoint:</strong> <code>https://[username].github.io</code> shows your page, from any device.</p><p><strong>Adding pages later:</strong> a file at <code>game/index.html</code> in the same repository appears at <code>https://[username].github.io/game/</code>. A file called <code>about.html</code> appears at <code>https://[username].github.io/about.html</code>.</p><h3 id="a-project-site" tabindex="-1">A project site <a class="header-anchor" href="#a-project-site" aria-label="Permalink to &quot;A project site&quot;">​</a></h3><p>Any other public repository can have its own site too, such as Project 1.</p><ol><li>Make sure the repository is <strong>public</strong> and has an <code>index.html</code> at the top level.</li><li><strong>Settings</strong> → <strong>Pages</strong> → <strong>Source:</strong> <strong>Deploy from a branch</strong> → <strong>Branch:</strong> <strong><code>main</code></strong> and <strong><code>/ (root)</code></strong> → <strong>Save</strong>.</li><li>Wait for the green tick in the <strong>Actions</strong> tab.</li><li>The site appears at <code>https://[username].github.io/[repository-name]/</code>.</li></ol><p>Every time you commit to <code>main</code>, GitHub republishes the site automatically. Give it a minute, then reload.</p><h2 id="fix-a-github-pages-404" tabindex="-1">Fix a GitHub Pages 404 <a class="header-anchor" href="#fix-a-github-pages-404" aria-label="Permalink to &quot;Fix a GitHub Pages 404&quot;">​</a></h2><p>A <strong>404</strong> means &quot;page not found&quot;: the address doesn&#39;t match a file GitHub is publishing. Work down this table.</p><table tabindex="0"><thead><tr><th>What you see</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;There isn&#39;t a GitHub Pages site here&quot;</td><td>Pages isn&#39;t turned on, it&#39;s still building, or the address is wrong</td><td>Check <strong>Settings</strong> → <strong>Pages</strong>. Look for a green tick in <strong>Actions</strong>. Copy the address from <strong>Visit site</strong> rather than typing it</td></tr><tr><td><strong>Settings</strong> → <strong>Pages</strong> says to upgrade or make the repository public</td><td>The repository is private</td><td>Make it public (<strong>Settings</strong> → <strong>General</strong> → <strong>Danger Zone</strong> → <strong>Change visibility</strong>), after checking it contains no secrets</td></tr><tr><td>Your README appears instead of your page</td><td>There&#39;s no <code>index.html</code> at the top level</td><td>Rename your page to <code>index.html</code> (lowercase) and move it out of any folder</td></tr><tr><td>The home page works but a sub-page is 404</td><td>The folder or file name doesn&#39;t match the address exactly. Names are case-sensitive</td><td>Compare letter by letter: <code>game/</code> versus <code>Game/</code>, <code>index.html</code> versus <code>index.html.txt</code></td></tr><tr><td>The page loads but has no styling or images</td><td>The file paths in your HTML are wrong</td><td>Use relative paths like <code>style.css</code> or <code>images/cat.png</code>. On a project site, a path starting with <code>/</code> points at <code>[username].github.io</code>, not your project</td></tr><tr><td>You still see the old version</td><td>The browser cached (saved) the old copy, or the build hasn&#39;t finished</td><td>Wait for the green tick, then hard-reload: <code>Ctrl+Shift+R</code> (Windows, Linux) or <code>Cmd+Shift+R</code> (macOS)</td></tr><tr><td>A red cross in <strong>Actions</strong></td><td>The build failed</td><td>Open the failed run and read the error. GitHub Pages runs a tool called Jekyll on your files. Adding an empty file named <code>.nojekyll</code> at the top level turns it off and fixes most failures</td></tr><tr><td>Files or folders whose names start with <code>_</code> are missing</td><td>Jekyll ignores them</td><td>Add an empty <code>.nojekyll</code> file at the top level, or rename them</td></tr></tbody></table><p>Still stuck? See <a href="./../resources/troubleshooting.html">Troubleshooting</a>, or ask your chat assistant, pasting the exact error text and your repository&#39;s file list (never a password or key).</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><ul><li>Week 2 uses the web upload and GitHub Pages: <a href="./../weeks/02-ship-your-page/">weeks/02-ship-your-page</a>.</li><li>Weeks 3 and 4 use github.dev, history and reverting: <a href="./../weeks/03-prompting-and-save-points/">weeks/03-prompting-and-save-points</a> and <a href="./../weeks/04-undo-compare-explain/">weeks/04-undo-compare-explain</a>.</li><li>You first open a Codespace in week 4, and from week 6 you work in one: <a href="./codespaces.html">GitHub Codespaces</a>.</li><li>How the web fits together (HTML, CSS, JavaScript, servers): <a href="./../resources/web-basics.html">How the Web Works</a>.</li></ul>`,78)])])}const u=t(a,[["render",r]]);export{g as __pageData,u as default};
